async def act(page):
    """
    From the current Orders grid state: set Status filter to 'Canceled', search, iterate all pages to collect cancelled orders,
    determine the customer with the most cancellations, visit that customer's cancelled order detail pages, compute
    each order's item total (sum of product price * qty) and created timestamp, find the most recent cancelled order(s),
    sum their item totals, print and return the formatted value (two decimals).
    """
    import re
    import time
    from urllib.parse import urljoin, urlparse

    # There are no helper functions in the provided knowledge base applicable to this task.

    # Build origin for absolute urls
    try:
        parsed = urlparse(page.url or "")
        if parsed.scheme and parsed.netloc:
            origin = f"{parsed.scheme}://{parsed.netloc}"
        else:
            origin = 'http://dockerized-magento.local'
    except Exception:
        origin = 'http://dockerized-magento.local'

    # Locate the main orders table (the one that has the "Order #" header link)
    try:
        orders_table = page.get_by_role("table").filter(has=page.get_by_role("link", name="Order #")).first()
    except Exception:
        orders_table = page.get_by_role("table").first()

    # Identify header and filter rows and important column indices (Status, Bill to Name (customer), Action)
    status_idx = None
    customer_idx = None
    action_idx = None
    header_row = None
    try:
        header_row = orders_table.get_by_role("row").nth(0)
        header_cells = header_row.get_by_role("cell")
        header_count = await header_cells.count()
        for i in range(header_count):
            try:
                cell = header_cells.nth(i)
                # prefer explicit link names if present
                if await cell.get_by_role("link", name="Status").count() > 0:
                    status_idx = i
                if await cell.get_by_role("link", name="Bill to Name").count() > 0 or await cell.get_by_role("link", name="Bill to").count() > 0:
                    customer_idx = i
                # action usually last column titled 'Action'
                txt = (await cell.inner_text() or "").strip().lower()
                if 'action' in txt:
                    action_idx = i
            except Exception:
                continue
    except Exception:
        header_row = None

    # If we couldn't find some indices by link detection, fall back to textual heuristics
    try:
        if status_idx is None and header_row is not None:
            header_count = await header_row.get_by_role('cell').count()
            for i in range(header_count):
                try:
                    txt = (await header_row.get_by_role('cell').nth(i).inner_text() or '').lower()
                    if 'status' in txt:
                        status_idx = i
                    if 'bill to' in txt or 'bill to name' in txt or 'bill to' in txt:
                        if customer_idx is None:
                            customer_idx = i
                    if 'action' in txt and action_idx is None:
                        action_idx = i
                except Exception:
                    continue
    except Exception:
        pass

    # Filter row is usually index 1
    filter_row_index = 1

    # Try to set status filter to 'Canceled'
    try:
        if status_idx is not None:
            filter_row = orders_table.get_by_role('row').nth(filter_row_index)
            status_cell = filter_row.get_by_role('cell').nth(status_idx)
            if await status_cell.get_by_role('combobox').count() > 0:
                combo = status_cell.get_by_role('combobox').nth(0)
                try:
                    await combo.select_option(label='Canceled')
                except Exception:
                    # try alternate spelling
                    try:
                        await combo.select_option(label='Cancelled')
                    except Exception:
                        pass

        # Click the Search button (use full path via containing table to avoid ambiguity)
        search_table = page.get_by_role('table').filter(has=page.get_by_role('button', name='Search')).first()
        if await search_table.get_by_role('button', name='Search').count() > 0:
            await search_table.get_by_role('button', name='Search').nth(0).click()
            await page.wait_for_load_state('networkidle')
            await page.wait_for_timeout(400)
    except Exception:
        # proceed even if filtering fails
        pass

    # Determine pagination: find the table that contains 'Go to Next page' link and parse "of N pages"
    try:
        pag_table = page.get_by_role('table').filter(has=page.get_by_role('link', name='Go to Next page')).first()
        pag_text = (await pag_table.inner_text()) or ''
        m = re.search(r'of\s*(\d+)\s*pages', pag_text, re.IGNORECASE)
        total_pages = int(m.group(1)) if m else 1
    except Exception:
        total_pages = 1

    # Collect cancelled orders across pages (finite loop)
    canceled_orders = []  # dicts: {href, customer, order_number, date_text}

    # We'll iterate pages sequentially by using the "Go to Next page" link.
    for page_index in range(1, total_pages + 1):
        # Wait briefly for content
        await page.wait_for_load_state('networkidle')
        await page.wait_for_timeout(300)

        # Refresh orders_table locator (DOM may have changed)
        try:
            orders_table = page.get_by_role("table").filter(has=page.get_by_role("link", name="Order #")).first()
        except Exception:
            orders_table = page.get_by_role('table').first()

        # Determine number of rows and starting index for data rows
        try:
            total_rows = await orders_table.get_by_role('row').count()
        except Exception:
            total_rows = 0

        # Data rows typically start after header and filter: index 2
        data_start = 2 if total_rows > 2 else 1

        for r in range(data_start, total_rows):
            try:
                row = orders_table.get_by_role('row').nth(r)
                # Read row text to ensure it's a cancelled order (after filter this should be true)
                try:
                    row_text = (await row.inner_text()) or ''
                except Exception:
                    row_text = ''
                if 'cancel' not in row_text.lower():
                    # skip non-cancelled
                    continue

                # customer
                customer = ''
                if customer_idx is not None:
                    try:
                        customer = (await row.get_by_role('cell').nth(customer_idx).inner_text()) or ''
                    except Exception:
                        customer = ''

                # date (if present) -- attempt best-effort using likely column index (Purchased On is often index 3)
                date_text = ''
                # try find a cell that contains a month name pattern if we didn't detect a date column
                try:
                    # attempt to read by likely index 3
                    if await row.get_by_role('cell').count() > 3:
                        date_text = (await row.get_by_role('cell').nth(3).inner_text()) or ''
                except Exception:
                    date_text = ''

                # order view link (Action -> View) or any link in row
                href = None
                order_number = ''
                try:
                    # prefer explicit 'View' link
                    if await row.get_by_role('link', name='View').count() > 0:
                        l = row.get_by_role('link', name='View').nth(0)
                        href = await l.get_attribute('href')
                    else:
                        # any link in row
                        if await row.get_by_role('link').count() > 0:
                            l = row.get_by_role('link').nth(0)
                            href = await l.get_attribute('href')
                            try:
                                order_number = (await l.inner_text()) or ''
                            except Exception:
                                order_number = ''
                except Exception:
                    href = None

                canceled_orders.append({
                    'href': href,
                    'customer': (customer or '').strip(),
                    'date_text': (date_text or '').strip(),
                    'order_number': (order_number or '').strip()
                })
            except Exception:
                continue

        # If more pages remain, click Go to Next page
        if page_index < total_pages:
            try:
                # Re-locate pagination table and click next
                pag_table = page.get_by_role('table').filter(has=page.get_by_role('link', name='Go to Next page')).first()
                if await pag_table.get_by_role('link', name='Go to Next page').count() > 0:
                    await pag_table.get_by_role('link', name='Go to Next page').nth(0).click()
                    await page.wait_for_load_state('networkidle')
                    await page.wait_for_timeout(400)
                else:
                    break
            except Exception:
                break

    # If no canceled orders found, return zero
    if not canceled_orders:
        print('0.00')
        return '0.00'

    # Count cancellations per customer using grid names when available
    counts = {}
    for o in canceled_orders:
        name = o.get('customer') or '<<UNKNOWN>>'
        counts[name] = counts.get(name, 0) + 1

    # Determine provisional top customer
    most_customer = None
    most_count = 0
    for name, c in counts.items():
        if c > most_count:
            most_count = c
            most_customer = name

    # If top is unknown or there are unknowns, try to resolve customer names by visiting order detail pages for orders with unknown customer
    if most_customer == '<<UNKNOWN>>' or any(k == '<<UNKNOWN>>' for k in counts.keys()):
        counts = {}
        for o in canceled_orders:
            cname = o.get('customer') or ''
            if cname:
                counts[cname] = counts.get(cname, 0) + 1
                continue
            href = o.get('href')
            if not href:
                continue
            abs_href = href if href.startswith('http') else urljoin(origin, href)
            try:
                await page.goto(abs_href)
                await page.wait_for_load_state('networkidle')
                await page.wait_for_timeout(200)
                info = await page.evaluate(r"""
                    (() => {
                        let candidate = '';
                        const all = Array.from(document.querySelectorAll('dt, th, strong, label, p, div, span'));
                        for(const el of all){
                            const t=(el.innerText||'').trim();
                            if(/Customer Name|Customer|Bill to|Billing Address|Billing Information|Customer:/i.test(t)){
                                if(el.nextElementSibling && el.nextElementSibling.innerText){ candidate = el.nextElementSibling.innerText.trim(); break; }
                                if(el.parentElement){ const pt = el.parentElement.innerText.replace(t,'').trim(); if(pt){ candidate = pt.split('\n')[0].trim(); break; }}
                            }
                        }
                        if(!candidate){ const h = document.querySelector('h1, h2, h3, strong'); if(h) candidate = h.innerText.trim(); }
                        return {customer: candidate};
                    })()
                """)
                cname = (info.get('customer') or '').strip() if isinstance(info, dict) else ''
                if not cname:
                    cname = '<<UNKNOWN>>'
                counts[cname] = counts.get(cname, 0) + 1
            except Exception:
                continue
        most_customer = None
        most_count = 0
        for name, c in counts.items():
            if c > most_count:
                most_count = c
                most_customer = name

    if not most_customer:
        print('0.00')
        return '0.00'

    # Collect the canceled orders that belong to the top customer (if grid had customer names) or verify detail pages
    candidate_orders = []
    for o in canceled_orders:
        if o.get('customer'):
            if o.get('customer') == most_customer:
                candidate_orders.append(o)
        else:
            candidate_orders.append(o)

    # Visit each candidate order detail page (verify customer if necessary) and extract createdAt and item_total
    detailed = []  # {href, createdAt, item_total}

    for o in candidate_orders:
        href = o.get('href')
        if not href:
            continue
        abs_href = href if href.startswith('http') else urljoin(origin, href)
        try:
            await page.goto(abs_href)
            await page.wait_for_load_state('networkidle')
            await page.wait_for_timeout(200)

            # If grid had no reliable customer name for this row, verify the customer in detail page
            if not o.get('customer'):
                info_c = await page.evaluate(r"""
                    (() => {
                        let candidate = '';
                        const all = Array.from(document.querySelectorAll('dt, th, strong, label, p, div, span'));
                        for(const el of all){
                            const t=(el.innerText||'').trim();
                            if(/Customer Name|Customer|Bill to|Billing Address|Billing Information|Customer:/i.test(t)){
                                if(el.nextElementSibling && el.nextElementSibling.innerText){ candidate = el.nextElementSibling.innerText.trim(); break; }
                                if(el.parentElement){ const pt = el.parentElement.innerText.replace(t,'').trim(); if(pt){ candidate = pt.split('\n')[0].trim(); break; }}
                            }
                        }
                        if(!candidate){ const h = document.querySelector('h1, h2, h3, strong'); if(h) candidate = h.innerText.trim(); }
                        return {customer: candidate};
                    })()
                """)
                detail_cname = (info_c.get('customer') or '').strip() if isinstance(info_c, dict) else ''
                if detail_cname and detail_cname != most_customer:
                    # skip: different customer
                    continue

            # Extract createdAt and item_total
            info = await page.evaluate(r"""
                (() => {
                    function parsePrice(s){ if(!s) return 0; const num = (''+s).replace(/[^0-9\.,\-]/g,'').replace(/,/g,''); const v = parseFloat(num); return isNaN(v)?0:v; }
                    const tables = Array.from(document.querySelectorAll('table'));
                    let itemsTable = null;
                    for(const t of tables){
                        const ths = Array.from(t.querySelectorAll('th')).map(h=>h.innerText.trim());
                        if(ths.some(h=>/Product/i.test(h)) && (ths.some(h=>/Qty|Quantity/i.test(h)) || ths.some(h=>/Subtotal|Price/i.test(h)))){ itemsTable = t; break; }
                    }
                    let item_total = 0;
                    if(itemsTable){
                        const rows = Array.from(itemsTable.querySelectorAll('tbody tr')).filter(r=>r.querySelectorAll('td').length>0);
                        for(const r of rows){
                            const txt = r.innerText || '';
                            const priceMatches = txt.match(/[$€£]?\s*[0-9\.,]+/g) || [];
                            let price = 0;
                            if(priceMatches.length){
                                const nums = priceMatches.map(s=>parseFloat((''+s).replace(/[^0-9\.-]/g,'').replace(/,/g,''))).filter(n=>!isNaN(n));
                                if(nums.length) price = Math.max.apply(null, nums);
                            }
                            let qty = 1;
                            const mQty = txt.match(/Qty[:\s]*([0-9]+)/i) || txt.match(/Quantity[:\s]*([0-9]+)/i);
                            if(mQty) qty = parseFloat(mQty[1]);
                            else{
                                const ints = Array.from(txt.matchAll(/\b([0-9]+)\b/g)).map(m=>parseInt(m[1],10));
                                if(ints.length===1) qty = ints[0];
                            }
                            item_total += price * qty;
                        }
                    } else {
                        const body = document.body.innerText || '';
                        const m = body.match(/Items Ordered[\s\S]*?Subtotal[:\s]*[$]?\s*([0-9,]+\.?[0-9]*)/i);
                        if(m) item_total = parseFloat(m[1].replace(/,/g,''));
                    }

                    let createdAt = null;
                    const all = Array.from(document.querySelectorAll('dt, th, strong, label, p, div, span'));
                    for(const el of all){
                        const t = (el.innerText||'').trim();
                        if(/Purchased On|Order Date|Created At|Purchased on/i.test(t)){
                            let val = '';
                            if(el.nextElementSibling && el.nextElementSibling.innerText){ val = el.nextElementSibling.innerText.trim(); }
                            else if(el.parentElement){ val = el.parentElement.innerText.replace(t,'').trim(); }
                            if(val){ const p = Date.parse(val); if(!isNaN(p)){ createdAt = p; break; } }
                        }
                    }
                    if(!createdAt){
                        const top = (document.body.innerText||'').split('\n').slice(0,40).join(' ');
                        const m2 = top.match(/([A-Za-z]{3,9}\s+\d{1,2},\s*\d{4}(?:\s+\d{1,2}:\d{2})?)/);
                        if(m2){ const p = Date.parse(m2[1]); if(!isNaN(p)) createdAt = p; }
                    }
                    return {createdAt: createdAt, item_total: item_total};
                })()
            """)

            createdAt = None
            item_total = 0.0
            try:
                if isinstance(info, dict):
                    createdAt = info.get('createdAt')
                    item_total = info.get('item_total') if info.get('item_total') is not None else 0.0
            except Exception:
                createdAt = None
                item_total = 0.0

            try:
                item_total = float(item_total) if item_total is not None else 0.0
            except Exception:
                item_total = 0.0

            if createdAt is not None:
                try:
                    createdAt = int(createdAt)
                except Exception:
                    createdAt = None

            # fallback to grid date_text if available
            if not createdAt and o.get('date_text'):
                try:
                    from datetime import datetime
                    parsed_dt = None
                    dt_text = o.get('date_text')
                    for fmt in ("%b %d, %Y %I:%M:%S %p", "%b %d, %Y %I:%M %p", "%b %d, %Y", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
                        try:
                            parsed_dt = datetime.strptime(dt_text, fmt)
                            break
                        except Exception:
                            parsed_dt = None
                    if parsed_dt:
                        createdAt = int(parsed_dt.timestamp() * 1000)
                except Exception:
                    createdAt = None

            if not createdAt:
                createdAt = int(time.time() * 1000)

            detailed.append({'href': abs_href, 'createdAt': int(createdAt), 'item_total': float(item_total)})

        except Exception:
            continue

    if not detailed:
        print('0.00')
        return '0.00'

    # Find most recent timestamp and sum item_totals for orders within 1s of that timestamp
    max_ts = max(d['createdAt'] for d in detailed)
    recent = [d for d in detailed if abs(d['createdAt'] - max_ts) <= 1000]

    total_sum = sum(d['item_total'] for d in recent)
    output_value = f"{total_sum:.2f}"
    print(output_value)
    return output_value

