    import time

    # Step 1: Navigate to Orders grid using relative goto
    await page.goto('../sales_order/')
    await page.wait_for_load_state('networkidle')
    await page.wait_for_timeout(300)

    # Step 2: Find the orders table (prefer table that has a 'Status' column)
    try:
        orders_table = page.get_by_role("table").filter(
            has=page.get_by_role("columnheader", name="Status")
        ).first()
        # If filter matched nothing, fall back to first table
        if await orders_table.count() == 0:
            orders_table = page.get_by_role("table").first()
    except Exception:
        orders_table = page.get_by_role("table").first()

    # Wait a bit for table content to render
    await page.wait_for_timeout(300)

    # Ensure table exists
    try:
        total_rows = await orders_table.get_by_role("row").count()
    except Exception:
        total_rows = 0

    if total_rows == 0:
        # No orders present
        print("0.00")
        return "0.00"

    # Determine header row and indices for Status, Customer, Date (if present)
    status_idx = None
    customer_idx = None
    date_idx = None

    try:
        header_row = orders_table.get_by_role("row").nth(0)
        header_count = await header_row.get_by_role("columnheader").count()
        for i in range(header_count):
            try:
                h = (await header_row.get_by_role("columnheader").nth(i).inner_text()) or ""
                h_l = h.strip().lower()
                if status_idx is None and 'status' in h_l:
                    status_idx = i
                if customer_idx is None and 'customer' in h_l:
                    customer_idx = i
                if date_idx is None and (('date' in h_l) or ('purchased' in h_l) or ('created' in h_l)):
                    date_idx = i
            except Exception:
                continue
    except Exception:
        # No explicit header row detected
        header_row = None

    # If there's a header row, skip it when iterating
    start_index = 1 if header_row is not None and total_rows > 0 else 0

    canceled_orders = []  # entries: {href, customer, date_text, order_number}

    for r in range(start_index, total_rows):
        try:
            row = orders_table.get_by_role("row").nth(r)
            # fetch status text
            status_text = ''
            try:
                if status_idx is not None:
                    status_text = (await row.get_by_role("cell").nth(status_idx).inner_text()) or ''
                else:
                    status_text = (await row.inner_text()) or ''
            except Exception:
                status_text = ''

            if 'cancel' not in status_text.lower():
                continue

            # customer cell
