                    parsed_dt = None
                    dt_text = o.get('date_text')
                    for fmt in ("%b %d, %Y %I:%M:%S %p", "%b %d, %Y %I:%M %p", "%b %d, %Y", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
                        try:
                            parsed_dt = datetime.strptime(dt_text, fmt)
                            break
                        except Exception:
                            parsed_dt = None
                    if parsed_dt:
                        createdAt = int(parsed_dt.timestamp() * 1000)
                except Exception:
                    createdAt = None

            if not createdAt:
                createdAt = int(time.time() * 1000)

            detailed.append({'href': abs_href, 'createdAt': int(createdAt), 'item_total': float(item_total)})

        except Exception:
            continue

    if not detailed:
        print('0.00')
        return '0.00'

    # Find most recent timestamp and sum item_totals for orders within 1s of that timestamp
    max_ts = max(d['createdAt'] for d in detailed)
    recent = [d for d in detailed if abs(d['createdAt'] - max_ts) <= 1000]

    total_sum = sum(d['item_total'] for d in recent)
    output_value = f"{total_sum:.2f}"
    print(output_value)
    return output_value
